insert into public.skill_definitions
  (id, name, description, kind, hidden, conditions, effect, locks, owner_limit, evolves_from, excludes, uses_per_battle, rumor, enabled)
values
  ('storm_sovereign', 'Storm Sovereign', 'Change the weather of the whole zone for 3 minutes: a heat wave, a thunderstorm, a blizzard or a hurricane, by element. It hits everyone in the zone, friend and foe.', 'active', true, '{"counter":"element_spells_outdoors","op":">=","value":10000}'::jsonb, '{}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, null, false),
  ('spell_thief', 'Spell Thief', 'When an enemy spell hits you, you absorb it and cast it back at double power. Once per enemy per fight.', 'passive', true, '{"counter":"spells_survived","op":">=","value":1000}'::jsonb, '{"passive":{"spell_thief":{"mult":2}}}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, null, true),
  ('chain_catastrophe', 'Chain Catastrophe', 'Every enemy your spell kills explodes into the same spell, so one spell can chain across the battlefield. Needs a staff in hand.', 'passive', true, '{"counter":"spell_multikills_10","op":">=","value":100}'::jsonb, '{"weapons":["staff"],"passive":{"chain_catastrophe":{"radius":150}}}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, null, true),
  ('blood_sorcery', 'Blood Sorcery', 'At 0 MP, your attack spells cost HP instead (1% of max HP per MP) and hit at double power. Needs a staff in hand.', 'passive', true, '{"counter":"zero_mp_kills","op":">=","value":100}'::jsonb, '{"weapons":["staff"],"passive":{"blood_sorcery":{"hp_per_mp":0.01,"mult":2}}}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, null, true),
  ('star_fall', 'Star Fall', 'Ultimate, bosses only. MP you spend in the boss fight charges the gauge. 500: a meteor for 50% of the boss''s HP (once per fight, resets the gauge). 1,000: a meteor that ends the boss. 2,000: a meteor shower that ends the boss and wipes the field, + 20% EXP.', 'active', true, '{"counter":"boss_fight_mp_spent_best","op":">=","value":5000}'::jsonb, '{"active":{"ultimate":{"gauge":"boss_mp_spent","tiers":[500,1000,2000],"field":true}}}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, null, true),
  ('grace_rebound', 'Grace Rebound', 'Your first heal below 10% HP in each fight is tripled.', 'passive', true, '{"counter":"low_hp_heals","op":">=","value":500}'::jsonb, '{"passive":{"grace_rebound":{"below":0.1,"mult":3}}}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, null, true),
  ('divine_blessing', 'Divine Blessing', 'You and your party get +10% to all stats for 60 seconds. 5 minute cooldown. After 20,000 buffs it grows to +20%.', 'active', true, '{"counter":"buffs_cast","op":">=","value":5000}'::jsonb, '{}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, null, false),
  ('soul_drain', 'Soul Drain', 'Every hit drains 25% of its damage as HP. HP beyond your max becomes a shield. Needs a healing bracelet in hand.', 'passive', true, '{"counter":"hits_healing_bracelet","op":">=","value":10000}'::jsonb, '{"weapons":["healing_bracelet"],"passive":{"soul_drain":{"pct":0.25,"max_shield":1}}}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, null, true),
  ('purify', 'Purify', 'When you cleanse a status, it bounces back to whoever caused it.', 'passive', true, '{"counter":"statuses_cleansed","op":">=","value":2000}'::jsonb, '{}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, null, false),
  ('judgment_of_mercy', 'Judgment of Mercy', 'Ultimate, bosses only. HP you heal or drain in the boss fight charges the gauge. 10,000: a holy burst for 50% of the boss''s HP (once per fight, resets the gauge). 20,000: a full kill. 40,000: a full kill + 20% EXP.', 'active', true, '{"counter":"boss_fight_healed_best","op":">=","value":50000}'::jsonb, '{"active":{"ultimate":{"gauge":"boss_healed","tiers":[10000,20000,40000]}}}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, null, true),
  ('curse_ward', 'Curse Ward', 'Curses on you last half as long. Needs a healing bracelet in hand.', 'passive', true, '{"counter":"curses_received","op":">=","value":500}'::jsonb, '{}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, null, false),
  ('hallowed_soul', 'Hallowed Soul', 'Immune to Curse while Divine Blessing is active. Needs a healing bracelet in hand.', 'passive', true, '{"counter":"curses_received","op":">=","value":2000}'::jsonb, '{}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, null, false),
  ('comet_charge', 'Comet Charge', 'Charge damage grows with the distance you run, up to double at a full run. Needs a lance in hand.', 'passive', true, '{"counter":"max_charge_kills","op":">=","value":1000}'::jsonb, '{"weapons":["lance"],"passive":{"comet_charge":{"max_mult":2}}}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, null, true),
  ('skewer', 'Skewer', 'Thrusts pierce through every enemy in a line.', 'passive', true, '{"counter":"multi_thrusts","op":">=","value":500}'::jsonb, '{}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, null, false),
  ('iron_momentum', 'Iron Momentum', 'While charging, you can''t be stunned or knocked back. Needs a lance in hand.', 'passive', true, '{"counter":"charges_done","op":">=","value":1000}'::jsonb, '{"weapons":["lance"],"passive":{"iron_momentum":true}}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, null, true),
  ('sky_lance', 'Sky Lance', 'Attack in the air to dive down and crash, hitting every enemy where you land. Needs a lance in hand.', 'passive', true, '{"counter":"jump_kills","op":">=","value":100}'::jsonb, '{"weapons":["lance"],"passive":{"sky_lance":{"reach":150}}}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, null, true),
  ('dragonpiercer', 'Dragonpiercer', 'Ultimate, bosses only. Each charge that hits the boss charges the gauge. 15: 50% of the boss''s HP (once per fight, resets the gauge). 30: a full kill. 60: a full kill + 20% EXP. Needs a lance in hand.', 'active', true, '{"counter":"boss_fight_charge_hits_best","op":">=","value":100}'::jsonb, '{"weapons":["lance"],"active":{"ultimate":{"gauge":"boss_charges","tiers":[15,30,60]}}}'::jsonb, '{}'::text[], null, null, '{}'::text[], null, null, true)
